type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const clone = (v: any): any => JSON.parse(JSON.stringify(v));
  let rows = clone(d.rows);
  if (d.where)
    rows = rows.filter((r: any) =>
      Object.keys(d.where).every((k) => {
        const c = d.where[k];
        return c && typeof c === "object"
          ? Object.keys(c).every((op) =>
              op === "gt"
                ? r[k] > c[op]
                : op === "lt"
                  ? r[k] < c[op]
                  : op === "in"
                    ? c[op].includes(r[k])
                    : r[k] === c[op],
            )
          : r[k] === c;
      }),
    );
  if (d.orderBy) {
    const orders = Array.isArray(d.orderBy) ? d.orderBy : [d.orderBy];
    rows.sort((a: any, b: any) => {
      for (const o of orders) {
        const x = a[o.key],
          y = b[o.key];
        if (x !== y) return (x < y ? -1 : 1) * (o.direction === "desc" ? -1 : 1);
      }
      return 0;
    });
  }
  if (d.offset) rows = rows.slice(d.offset);
  if (d.limit !== undefined) rows = rows.slice(0, d.limit);
  if (d.select)
    rows = rows.map((r: any) =>
      Object.fromEntries(Object.entries(d.select).map(([alias, key]) => [alias, r[key as string]])),
    );
  return rows;
}
